38	    /**
39	     * This constructor allows caller to build metrics name with custom package and class name. This is useful to keep metrics
40	     * compatibility in migrating scala code, since the difference of either package or class name will impact the mbean name and
41	     * that will break the backward compatibility.
42	     */
43	    public KafkaMetricsGroup(String packageName, String simpleName) {
44	        this.pkg = packageName;
45	        this.simpleName = simpleName;
46	    }
47	
48	    /**
49	     * Creates a new MetricName object for gauges, meters, etc. created for this
50	     * metrics group.
51	     * @param name Descriptive name of the metric.
52	     * @param tags Additional attributes which mBean will have.
53	     * @return Sanitized metric name object.
54	     */
55	    public MetricName metricName(String name, Map<String, String> tags) {
56	        return explicitMetricName(this.pkg, this.simpleName, name, tags);
57	    }
