59	    private static MetricName explicitMetricName(String group, String typeName,
60	                                                String name, Map<String, String> tags) {
61	        StringBuilder nameBuilder = new StringBuilder(100);
62	        nameBuilder.append(group);
63	        nameBuilder.append(":type=");
64	        nameBuilder.append(typeName);
65	
66	        if (!name.isEmpty()) {
67	            nameBuilder.append(",name=");
68	            nameBuilder.append(name);
69	        }
70	
71	        String scope = toScope(tags).orElse(null);
72	        Optional<String> tagsName = toMBeanName(tags);
73	        tagsName.ifPresent(s -> nameBuilder.append(",").append(s));
74	
75	        return new MetricName(group, typeName, name, scope, nameBuilder.toString());
76	    }
