        private final Logger logger;
        private final Map<String, String> metricTags;
        private volatile boolean isAllSegmentsValid = false;
        private volatile int retentionSizeInPercent = 0;
        private volatile int localRetentionSizeInPercent = 0;

        public RLMExpirationTask(TopicIdPartition topicIdPartition) {
            super(topicIdPartition);
            this.logger = getLogContext().logger(RLMExpirationTask.class);
            // Preserve the tag order so that the JMX name reads "partition=<partition>,topic=<topic>".
            Map<String, String> tags = new LinkedHashMap<>();
            tags.put("partition", String.valueOf(topicIdPartition.partition()));
            tags.put("topic", topicIdPartition.topic());
            this.metricTags = Collections.unmodifiableMap(tags);
        }

        // Visible for testing
        void registerMetrics() {
            metricsGroup.newGauge(RETENTION_SIZE_IN_PERCENT_METRIC.getName(), () -> retentionSizeInPercent, metricTags);
            metricsGroup.newGauge(LOCAL_RETENTION_SIZE_IN_PERCENT_METRIC.getName(), () -> localRetentionSizeInPercent, metricTags);
        }

        int retentionSizeInPercent() {
            return retentionSizeInPercent;
        }

        int localRetentionSizeInPercent() {
            return localRetentionSizeInPercent;
        }

        @Override
        protected void execute(UnifiedLog log) throws InterruptedException, RemoteStorageException, ExecutionException {
            cleanupExpiredRemoteLogSegments();
        }

        @Override
        public void cancel() {
            isAllSegmentsValid = false;
            metricsGroup.removeMetric(RETENTION_SIZE_IN_PERCENT_METRIC.getName(), metricTags);
            metricsGroup.removeMetric(LOCAL_RETENTION_SIZE_IN_PERCENT_METRIC.getName(), metricTags);
            retentionSizeInPercent = 0;
            localRetentionSizeInPercent = 0;
            super.cancel();
        }

